mapper.select:


    l.del_flag = '0'

        and l.supplier_id = #{supplierId}


        and l.person_id = #{personId}


        and l.person_name like concat('%', #{personName}, '%')


        and l.link_type = #{linkType}


        and l.source_type = #{sourceType}


        and l.handle_result = #{handleResult}


order by
    case l.handle_result when '0' then 0 else 1 end,
    l.create_time desc

select count(1) from jc_supplier_link
where del_flag = '0' and supplier_id = #{supplierId} and person_id = #{personId}
  and link_type = #{linkType} and handle_result <> '4'

select count(1) from jc_supplier_link
where del_flag = '0' and supplier_id = #{supplierId} and person_id = #{personId}
  and link_type = #{linkType} and source_type = #{sourceType}

mapper.update:
update jc_supplier_link
person_name = #{personName}, link_type = #{linkType}, hold_ratio = #{holdRatio}, source_type = #{sourceType}, evidence = #{evidence}, verify_status = #{verifyStatus}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where link_id = #{linkId}
